<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Support\Facades\Storage;
class AdCreative extends Model { use HasFactory,SoftDeletes; protected $fillable=['uuid','advertising_campaign_id','name','creative_type','status','media_path','mime_type','file_size','width','height','headline','body','cta_label','destination_url','alt_text','approved_at','approved_by','rejection_reason']; protected $casts=['approved_at'=>'datetime']; protected $appends=['media_url']; public function campaign(): BelongsTo{return $this->belongsTo(AdvertisingCampaign::class,'advertising_campaign_id');} public function approver(): BelongsTo{return $this->belongsTo(User::class,'approved_by');} public function getMediaUrlAttribute(): ?string{return $this->media_path?Storage::disk('public')->url($this->media_path):null;} }
